def transform(grid):
    # Grid is partitioned by full separator rows/columns. A region with
    # multiple marker cells becomes 1; a lone or empty region becomes bg.
    full_rows={v:sum(all(x==v for x in row) for row in grid) for v in set(x for row in grid for x in row)}
    sep=max(full_rows, key=full_rows.get)
    row_bars=[r for r,row in enumerate(grid) if all(v==sep for v in row)]
    col_bars=[c for c in range(len(grid[0])) if all(row[c]==sep for row in grid)]
    bounds_r=[-1]+row_bars+[len(grid)]
    bounds_c=[-1]+col_bars+[len(grid[0])]
    regions_r=[(a+1,b) for a,b in zip(bounds_r,bounds_r[1:]) if b>a+1]
    regions_c=[(a+1,b) for a,b in zip(bounds_c,bounds_c[1:]) if b>a+1]
    # The background is the color most common among cells not on the frame.
    counts={}
    for r0,r1 in regions_r:
        for c0,c1 in regions_c:
            for r in range(r0,r1):
                for c in range(c0,c1):
                    v=grid[r][c]
                    if v!=sep: counts[v]=counts.get(v,0)+1
    bg=max(counts,key=counts.get)
    out=[]
    for r0,r1 in regions_r:
        out.append([1 if sum(grid[r][c] not in (bg,sep) for r in range(r0,r1) for c in range(c0,c1))>1 else bg for c0,c1 in regions_c])
    return out

